import{_ as n,a0 as s,w as p,s as d,ao as i,I as e,a1 as l,A as o,x as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"在树莓派上玩怀旧游戏的 5 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"在树莓派上玩怀旧游戏的 5 种方法 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在树莓派上玩怀旧游戏的 5 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在树莓派上玩怀旧游戏的 5 种方法 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20180924 5 ways to play old-school games on a Raspberry Pi","title":"在树莓派上玩怀旧游戏的 5 种方法","tag":"201907","desc":""},"relativePath":"201907/20180924 5 ways to play old-school games on a Raspberry Pi.md","filePath":"[post].md"}'),b={name:"201907/20180924 5 ways to play old-school games on a Raspberry Pi.md"};function m(u,a,f,h,P,x){const t=s("Link");return p(),d("div",null,[a[50]||(a[50]=i('<h1 id="在树莓派上玩怀旧游戏的-5-种方法" tabindex="-1">在树莓派上玩怀旧游戏的 5 种方法 <a class="header-anchor" href="#在树莓派上玩怀旧游戏的-5-种方法" aria-label="Permalink to “在树莓派上玩怀旧游戏的 5 种方法”">​</a></h1><blockquote><p>使用这些用于树莓派的开源平台来重温游戏的黄金时代。</p></blockquote><p><img src="https://d3avoj45mekucs.cloudfront.net/rojakdaily/media/jessica-chua/lifestyle/retro%20gaming%20comeback/retro-video-game-event.jpg" alt=""></p><p>他们使它们不像过去那样子了，对吧？我是说，电子游戏。</p><p>当然，现在的设备更强大了。<ruby>赛达尔公主<rt>Princess Zelda</rt></ruby>在过去每个边只有 16 个像素，而现在的图像处理能力足够处理她头上的每根头发。今天的处理器打败 1988 年的处理器简直不费吹灰之力。</p><p>但是你知道缺少什么吗？乐趣。</p><p>你有数之不尽的游戏，按下一个按钮就可以完成教程任务。可能有故事情节，当然杀死坏蛋也可以不需要故事情节，你需要的只是跳跃和射击。因此，毫不奇怪，树莓派最持久的流行用途之一就是重温上世纪八九十年代的 8 位和 16 位游戏的黄金时代。但从哪里开始呢？</p><p>在树莓派上有几种方法可以玩怀旧游戏。每一种都有自己的优点和缺点，我将在这里讨论这些。</p><h3 id="retropie" tabindex="-1">RetroPie <a class="header-anchor" href="#retropie" aria-label="Permalink to “RetroPie”">​</a></h3>',9)),e("p",null,[l(t,{href:"https://retropie.org.uk/"},{default:o(()=>[...a[0]||(a[0]=[r("RetroPie",-1)])]),_:1}),a[1]||(a[1]=r(" 可能是树莓派上最受欢迎的复古游戏平台。它是一个可靠的万能选手，是模拟经典桌面和控制台游戏系统的绝佳选择。",-1))]),a[51]||(a[51]=e("p",null,[e("img",{src:"https://retropie.org.uk/wp-content/uploads/2016/04/Amiga_Gameplay_2.png",alt:""})],-1)),a[52]||(a[52]=e("h4",{id:"介绍",tabindex:"-1"},[r("介绍 "),e("a",{class:"header-anchor",href:"#介绍","aria-label":"Permalink to “介绍”"},"​")],-1)),e("p",null,[a[5]||(a[5]=r("RetroPie 构建在 ",-1)),l(t,{href:"https://www.raspbian.org/"},{default:o(()=>[...a[2]||(a[2]=[r("Raspbian",-1)])]),_:1}),a[6]||(a[6]=r(" 上运行。如果你愿意，它也可以安装在现有的 Raspbian 镜像上。它使用 ",-1)),l(t,{href:"https://emulationstation.org/"},{default:o(()=>[...a[3]||(a[3]=[r("EmulationStation",-1)])]),_:1}),a[7]||(a[7]=r(" 作为开源仿真器库（包括 ",-1)),l(t,{href:"https://www.libretro.com/"},{default:o(()=>[...a[4]||(a[4]=[r("Libretro",-1)])]),_:1}),a[8]||(a[8]=r(" 仿真器）的图形前端。",-1))]),a[53]||(a[53]=e("p",null,"不过，你要玩游戏其实并不需要理解上面的任何一个词。",-1)),a[54]||(a[54]=e("h4",{id:"它有什么好处",tabindex:"-1"},[r("它有什么好处 "),e("a",{class:"header-anchor",href:"#它有什么好处","aria-label":"Permalink to “它有什么好处”"},"​")],-1)),a[55]||(a[55]=e("p",null,"入门很容易。你需要做的就是将镜像刻录到 SD 卡，配置你的控制器、复制游戏，然后开始杀死坏蛋。",-1)),a[56]||(a[56]=e("p",null,"它的庞大用户群意味着有大量的支持和信息，活跃的在线社区也可以求助问题。",-1)),a[57]||(a[57]=e("p",null,"除了随 RetroPie 镜像一起安装的仿真器之外，还有一个可以从包管理器安装的庞大的仿真器库，并且它一直在增长。RetroPie 还提供了用户友好的菜单系统来管理这些，可以节省你的时间。",-1)),e("p",null,[a[11]||(a[11]=r("从 RetroPie 菜单中可以轻松添加 Kodi 和配备了 Chromium 浏览器的 Raspbian 桌面。这意味着你的这套复古游戏装备也适于作为家庭影院、",-1)),l(t,{href:"https://www.youtube.com/"},{default:o(()=>[...a[9]||(a[9]=[r("YouTube",-1)])]),_:1}),a[12]||(a[12]=r("、",-1)),l(t,{href:"https://soundcloud.com/"},{default:o(()=>[...a[10]||(a[10]=[r("SoundCloud",-1)])]),_:1}),a[13]||(a[13]=r(" 以及所有其它“休息室电脑”产品。",-1))]),a[58]||(a[58]=i('<p>RetroPie 还有许多其它自定义选项：你可以更改菜单中的图形，为不同的模拟器设置不同的控制手柄配置，使你的树莓派文件系统的所有内容对你的本地 Windows 网络可见等等。</p><p>RetroPie 建立在 Raspbian 上，这意味着你可以探索这个树莓派最受欢迎的操作系统。你所发现的大多数树莓派项目和教程都是为 Raspbian 编写的，因此可以轻松地自定义和安装新内容。我已经使用我的 RetroPie 装备作为无线桥接器，在上面安装了 MIDI 合成器，自学了一些 Python，更重要的是，所有这些都没有影响它作为游戏机的用途。</p><h4 id="它有什么不太好的" tabindex="-1">它有什么不太好的 <a class="header-anchor" href="#它有什么不太好的" aria-label="Permalink to “它有什么不太好的”">​</a></h4><p>RetroPie 的安装简单和易用性在某种程度上是一把双刃剑。你可以在 RetroPie 上玩了很长时间，而甚至没有学习过哪怕像 <code>sudo apt-get</code> 这样简单的东西，但这也意味着你错过了很多树莓派的体验。</p><p>但不一定必须如此；当你需要时，命令行仍然存在于底层，但是也许用户与 Bash shell 有点隔离，而使它最终并没有看上去那么可怕、另外，RetroPie 的主菜单只能通过控制手柄操作，当你没有接入手柄时，这可能很烦人，因为你一直将该系统用于游戏之外的事情。</p><h4 id="它适用于谁" tabindex="-1">它适用于谁? <a class="header-anchor" href="#它适用于谁" aria-label="Permalink to “它适用于谁?”">​</a></h4><p>任何想直接玩一些游戏的人，任何想拥有最大、最好的模拟器库的人，以及任何想在不玩游戏的时候开始探索 Linux 的人。</p><h3 id="recalbox" tabindex="-1">Recalbox <a class="header-anchor" href="#recalbox" aria-label="Permalink to “Recalbox”">​</a></h3>',8)),e("p",null,[l(t,{href:"https://www.recalbox.com/"},{default:o(()=>[...a[14]||(a[14]=[r("Recalbox",-1)])]),_:1}),a[15]||(a[15]=r(" 是一个较新的树莓派开源模拟器套件。它还支持其它基于 ARM 的小型计算机。",-1))]),a[59]||(a[59]=i('<p><img src="https://www.recalbox.com/images/features/4playermodo_hu5438825b9b6d1014226d20d231e650c2_230970_500x0_resize_q75_box.jpeg" alt=""></p><h4 id="介绍-1" tabindex="-1">介绍 <a class="header-anchor" href="#介绍-1" aria-label="Permalink to “介绍”">​</a></h4><p>与 Retropie 一样， Recalbox 基于 EmulationStation 和 Libretro。它的不同之处在于它不是基于 Raspbian 构建的，而是基于它自己的 Linux 发行版：RecalboxOS。</p><h4 id="它有什么好处-1" tabindex="-1">它有什么好处 <a class="header-anchor" href="#它有什么好处-1" aria-label="Permalink to “它有什么好处”">​</a></h4><p>Recalbox 的设置比 RetroPie 更容易。你甚至不需要做 SD 卡镜像；只需复制一些文件即可。它还为一些游戏控制器提供开箱即用的支持，可以让你更快地开始游戏。它预装了 Kodi。这是一个现成的游戏和媒体平台。</p><h4 id="它有什么不太好的-1" tabindex="-1">它有什么不太好的 <a class="header-anchor" href="#它有什么不太好的-1" aria-label="Permalink to “它有什么不太好的”">​</a></h4><p>Recalbox 比 RetroPie 拥有更少的仿真器、更少的自定义选项和更小的用户社区。</p><p>你的 Recalbox 装备可能一直用于模拟器和 Kodi，安装成什么样就是什么样。如果你想深入了解 Linux，你可能需要为 Raspbian 提供一个新的 SD 卡。</p><h4 id="它适用于谁-1" tabindex="-1">它适用于谁? <a class="header-anchor" href="#它适用于谁-1" aria-label="Permalink to “它适用于谁?”">​</a></h4><p>如果你想要绝对简单的复古游戏体验，并且不想玩一些比较少见的游戏平台模拟器，或者你害怕一些技术性工作（也没有兴趣去做），那么 Recalbox 非常适合你。</p><p>对于大多数读者来说，Recalbox 可能最适合推荐给你那些不太懂技术的朋友或亲戚。它超级简单的设置和几乎没什么选项甚至可以让你免去帮助他们解决问题。</p><h3 id="做个你自己的" tabindex="-1">做个你自己的 <a class="header-anchor" href="#做个你自己的" aria-label="Permalink to “做个你自己的”">​</a></h3><p>好，你可能已经注意到 Retropie 和 Recalbox 都是由许多相同的开源组件构建的。那么为什么不自己把它们组合在一起呢？</p><h4 id="介绍-2" tabindex="-1">介绍 <a class="header-anchor" href="#介绍-2" aria-label="Permalink to “介绍”">​</a></h4><p>无论你想要的是什么，开源软件的本质意味着你可以使用现有的模拟器套件作为起点，或者随意使用它们。</p><h4 id="它有什么好处-2" tabindex="-1">它有什么好处 <a class="header-anchor" href="#它有什么好处-2" aria-label="Permalink to “它有什么好处”">​</a></h4>',16)),e("p",null,[a[18]||(a[18]=r("如果你想有自己的自定义界面，我想除了亲自动手别无它法。这也是安装在 RetroPie 中没有的仿真器的方法，例如 ",-1)),l(t,{href:"http://www.mkw.me.uk/beebem/"},{default:o(()=>[...a[16]||(a[16]=[r("BeebEm",-1)])]),_:1}),a[19]||(a[19]=r(") 或 ",-1)),l(t,{href:"http://arcem.sourceforge.net/"},{default:o(()=>[...a[17]||(a[17]=[r("ArcEm",-1)])]),_:1}),a[20]||(a[20]=r("。",-1))]),a[60]||(a[60]=i('<h4 id="它有什么不太好的-2" tabindex="-1">它有什么不太好的 <a class="header-anchor" href="#它有什么不太好的-2" aria-label="Permalink to “它有什么不太好的”">​</a></h4><p>嗯，工作量有点大。</p><h4 id="它适用于谁-2" tabindex="-1">它适用于谁? <a class="header-anchor" href="#它适用于谁-2" aria-label="Permalink to “它适用于谁?”">​</a></h4><p>喜欢鼓捣的人，有动手能力的人，开发者，经验丰富的业余爱好者等。</p><h3 id="原生-risc-os-游戏体验" tabindex="-1">原生 RISC OS 游戏体验 <a class="header-anchor" href="#原生-risc-os-游戏体验" aria-label="Permalink to “原生 RISC OS 游戏体验”">​</a></h3>',5)),e("p",null,[a[22]||(a[22]=r("现在有一匹黑马：",-1)),l(t,{href:"https://opensource.com/article/18/7/gentle-intro-risc-os"},{default:o(()=>[...a[21]||(a[21]=[r("RISC OS",-1)])]),_:1}),a[23]||(a[23]=r("，它是 ARM 设备的原始操作系统。",-1))]),a[61]||(a[61]=i('<h4 id="介绍-3" tabindex="-1">介绍 <a class="header-anchor" href="#介绍-3" aria-label="Permalink to “介绍”">​</a></h4><p>在 ARM 成为世界上最受欢迎的 CPU 架构之前，它最初是作为 Acorn Archimedes 的处理器而开发的。现在看起来这像是一种被遗忘的野兽，但是那几年，它作为世界上最强大的台式计算机独领风骚了好几年，并且吸引了大量的游戏开发项目。</p><p>树莓派中的 ARM 处理器是 Archimedes 的曾孙辈的 CPU，所以我们仍然可以在其上安装 RISC OS，只要做一点工作，就可以让这些游戏运行起来。这与我们到上面所介绍的仿真器方式不同，我们是在玩为该操作系统和 CPU 架构开发的游戏。</p><h4 id="它有什么好处-3" tabindex="-1">它有什么好处 <a class="header-anchor" href="#它有什么好处-3" aria-label="Permalink to “它有什么好处”">​</a></h4><p>这是 RISC OS 的完美展现，这绝对是操作系统的瑰宝，非常值得一试。</p><p>事实上，你使用的是和以前几乎相同的操作系统来加载和玩你的游戏，这使得你的复古游戏装备像是一个时间机器一样，这无疑为该项目增添了一些魅力和复古价值。</p><p>有一些精彩的游戏只在 Archimedes 上发布过。Archimedes 的巨大硬件优势也意味着它通常拥有许多多平台游戏大作的最佳图形和最流畅的游戏体验。这类游戏的版权持有者非常慷慨，可以合法地免费下载它们。</p><h4 id="它有什么不太好的-3" tabindex="-1">它有什么不太好的 <a class="header-anchor" href="#它有什么不太好的-3" aria-label="Permalink to “它有什么不太好的”">​</a></h4>',8)),e("p",null,[a[25]||(a[25]=r("安装了 RISC OS 之后，它仍然需要一些努力才能让游戏运行起来。这是 ",-1)),l(t,{href:"https://blog.dxmtechsupport.com.au/playing-badass-acorn-archimedes-games-on-a-raspberry-pi/"},{default:o(()=>[...a[24]||(a[24]=[r("入门指南",-1)])]),_:1}),a[26]||(a[26]=r("。",-1))]),e("p",null,[a[29]||(a[29]=r("对于休息室来说，这绝对不是一个很好的全能选手。没有什么比 ",-1)),l(t,{href:"https://kodi.tv/"},{default:o(()=>[...a[27]||(a[27]=[r("Kodi",-1)])]),_:1}),a[30]||(a[30]=r(" 更好的了。它有一个网络浏览器 ",-1)),l(t,{href:"https://www.netsurf-browser.org/"},{default:o(()=>[...a[28]||(a[28]=[r("NetSurf",-1)])]),_:1}),a[31]||(a[31]=r("，但它在支持现代 Web 方面还需要一些努力。你不会像使用模拟器套件那样得到大量可以玩的游戏。RISC OS Open 对于爱好者来说可以免费下载和使用，而且很多源代码已经开源，尽管由于这个名字，它不是一个 100％ 的开源操作系统。",-1))]),a[62]||(a[62]=i('<h4 id="它适用于谁-3" tabindex="-1">它适用于谁? <a class="header-anchor" href="#它适用于谁-3" aria-label="Permalink to “它适用于谁?”">​</a></h4><p>这是专为追求新奇的人，绝对怀旧的人，想要探索一个来自上世纪 80 年代的有趣的操作系统的人，怀旧过去的 Acorn 机器的人，以及想要一个完全不同的怀旧游戏项目的人而设计的。</p><h3 id="终端游戏" tabindex="-1">终端游戏 <a class="header-anchor" href="#终端游戏" aria-label="Permalink to “终端游戏”">​</a></h3><p>你是否真的需要安装模拟器或者一个异域风情的操作系统才能重温辉煌的日子？为什么不从命令行安装一些原生 Linux 游戏呢？</p><h4 id="介绍-4" tabindex="-1">介绍 <a class="header-anchor" href="#介绍-4" aria-label="Permalink to “介绍”">​</a></h4>',5)),e("p",null,[a[33]||(a[33]=r("有一系列原生的 Linux 游戏经过测试可以在 ",-1)),l(t,{href:"https://www.raspberrypi.org/forums/viewtopic.php?f=78&t=51794"},{default:o(()=>[...a[32]||(a[32]=[r("树莓派",-1)])]),_:1}),a[34]||(a[34]=r(" 上运行。",-1))]),a[63]||(a[63]=i('<h4 id="它有什么好处-4" tabindex="-1">它有什么好处 <a class="header-anchor" href="#它有什么好处-4" aria-label="Permalink to “它有什么好处”">​</a></h4><p>你可以使用命令行从程序包安装其中的大部分，然后开始玩。很容易。如果你已经有了一个跑起来的 Raspbian，那么它可能是你运行游戏的最快途径。</p><h4 id="它有什么不太好的-4" tabindex="-1">它有什么不太好的 <a class="header-anchor" href="#它有什么不太好的-4" aria-label="Permalink to “它有什么不太好的”">​</a></h4><p>严格来说，这并不是真正的复古游戏。Linux 诞生于 1991 年，过了一段时间才成为了一个游戏平台。这些不是经典的 8 位和 16 位时代的游戏体验；后来有一些移植的游戏或受复古影响的游戏。</p><h4 id="它适用于谁-4" tabindex="-1">它适用于谁? <a class="header-anchor" href="#它适用于谁-4" aria-label="Permalink to “它适用于谁?”">​</a></h4><p>如果你只是想找点乐子，这没问题。但如果你想重温过去，那就不完全是这样了。</p><hr>',7)),e("p",null,[a[36]||(a[36]=r("via: ",-1)),l(t,{href:"https://opensource.com/article/18/9/retro-gaming-raspberry-pi"},{default:o(()=>[...a[35]||(a[35]=[r("https://opensource.com/article/18/9/retro-gaming-raspberry-pi",-1)])]),_:1})]),e("p",null,[a[41]||(a[41]=r("作者：",-1)),l(t,{href:"https://opensource.com/users/dxmjames"},{default:o(()=>[...a[37]||(a[37]=[r("James Mawson",-1)])]),_:1}),a[42]||(a[42]=r(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[38]||(a[38]=[r("lujun9972",-1)])]),_:1}),a[43]||(a[43]=r(" 译者：",-1)),l(t,{href:"https://github.com/canhetingsky"},{default:o(()=>[...a[39]||(a[39]=[r("canhetingsky",-1)])]),_:1}),a[44]||(a[44]=r(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[40]||(a[40]=[r("wxy",-1)])]),_:1})]),e("p",null,[a[47]||(a[47]=r("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[45]||(a[45]=[r("LCTT",-1)])]),_:1}),a[48]||(a[48]=r(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:o(()=>[...a[46]||(a[46]=[r("Linux中国",-1)])]),_:1}),a[49]||(a[49]=r(" 荣誉推出",-1))])])}const g=n(b,[["render",m]]);export{S as __pageData,g as default};
